using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Sigov.Application.Empresarial;
namespace Sigov.Api.Controllers;
[ApiController,Authorize,Route("api/empresarial/estoque")] public sealed class EmpresarialEstoqueController:ControllerBase { private readonly IEmpresarialService _service; public EmpresarialEstoqueController(IEmpresarialEstoqueService service)=>_service=service;
[HttpGet("dashboard")] public async Task<IActionResult> Dashboard(CancellationToken ct)=>Ok(await _service.DashboardAsync("emp_estoque_produto",ct));
[HttpGet("produtos")] public async Task<IActionResult> Listar_produtos([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>Ok(await _service.ListarAsync("emp_estoque_produto",pagina,tamanho,ct));
