[HttpGet("saldos")] public async Task<IActionResult> Listar_saldos([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>Ok(await _service.ListarAsync("emp_estoque_saldo",pagina,tamanho,ct));
