[HttpGet("movimentos")] public async Task<IActionResult> Listar_movimentos([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>Ok(await _service.ListarAsync("emp_estoque_movimento",pagina,tamanho,ct));
[HttpPost("movimentos")] public async Task<IActionResult> Criar_movimentos([FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.CriarAsync("emp_estoque_movimento",request,HttpContext.TraceIdentifier,ct));
[HttpGet("requisicoes")] public async Task<IActionResult> Listar_requisicoes([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>Ok(await _service.ListarAsync("emp_estoque_requisicao",pagina,tamanho,ct));
[HttpPost("requisicoes")] public async Task<IActionResult> Criar_requisicoes([FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.CriarAsync("emp_estoque_requisicao",request,HttpContext.TraceIdentifier,ct));
[HttpGet("inventarios")] public async Task<IActionResult> Listar_inventarios([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>Ok(await _service.ListarAsync("emp_estoque_inventario",pagina,tamanho,ct));
[HttpPost("inventarios")] public async Task<IActionResult> Criar_inventarios([FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.CriarAsync("emp_estoque_inventario",request,HttpContext.TraceIdentifier,ct));
[HttpGet("fornecedores")] public async Task<IActionResult> Listar_fornecedores([FromQuery]int pagina=1,[FromQuery]int tamanho=20,CancellationToken ct=default)=>Ok(await _service.ListarAsync("emp_compras_fornecedor",pagina,tamanho,ct));
[HttpPost("fornecedores")] public async Task<IActionResult> Criar_fornecedores([FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.CriarAsync("emp_compras_fornecedor",request,HttpContext.TraceIdentifier,ct));
