[HttpPost("compras")] public async Task<IActionResult> Criar_compras([FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.CriarAsync("emp_compras_pedido",request,HttpContext.TraceIdentifier,ct));
[HttpPost("requisicoes/{id:long}/aprovar")] public async Task<IActionResult> Acao0(long id,[FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.StatusAsync("emp_estoque_requisicao",id,"APROVADA",request.Justificativa,HttpContext.TraceIdentifier,ct));
[HttpPost("requisicoes/{id:long}/baixar")] public async Task<IActionResult> Acao1(long id,[FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.StatusAsync("emp_estoque_requisicao",id,"BAIXADA",request.Justificativa,HttpContext.TraceIdentifier,ct));
[HttpPost("compras/{id:long}/receber")] public async Task<IActionResult> Acao2(long id,[FromBody]EmpresarialOperacaoRequest request,CancellationToken ct)=>Ok(await _service.StatusAsync("emp_compras_pedido",id,"RECEBIDO",request.Justificativa,HttpContext.TraceIdentifier,ct));
[HttpGet("relatorios/resumo")] public async Task<IActionResult> Resumo(CancellationToken ct)=>Ok(await _service.DashboardAsync("emp_estoque_produto",ct));
[HttpGet("relatorios/exportar-csv")] public async Task<IActionResult> Csv(CancellationToken ct){var r=await _service.ListarAsync("emp_estoque_produto",1,100,ct);var csv="id;codigo;status;titulo\n"+string.Join("\n",r.Value?.Items.Select(x=>$"{x.Id};{x.Codigo};{x.Status};{x.Titulo}")??Array.Empty<string>());return File(System.Text.Encoding.UTF8.GetBytes(csv),"text/csv","estoque.csv");}
